// The Reuleaux Platonic Solids (DICTO 2026-10-21; DICTO's idea, paper #45, DICTO DOI 10.5281/zenodo.23529499) as Polyhedraverse
// shapes: for each Platonic solid, the common part of balls centred on its corners, of radius D (the solid's diameter). Named by look:
// balls on the tetrahedron make the Reuleaux tetrahedron, on the cube the Reuleaux octahedron, on the octahedron the Reuleaux cube, on
// the dodecahedron the Reuleaux icosahedron, on the icosahedron the Reuleaux dodecahedron.
// One body data (reuleaux-bodies.js, generated by kaleidohedra's scripts/build-reuleaux-data.py) serves this family and Kaleidohedra's
// Reuleaux world. Each shape is drawn at the size where its face corners are 1 apart (as the world's build), so its three-cornered faces
// meet every unit triangle. Its `vertices` and `faces` are the corners and each ball patch's corners (what fitting and snapping use);
// `curved` holds what is drawn: the smooth body, each triangle tagged with its patch (face), and the seams between patches (the creases).
import { specOf } from './stellaJewel.js';
import { REULEAUX_Q, REULEAUX_RAW } from './reuleaux-bodies.js';

export { REULEAUX_Q, REULEAUX_RAW };
/** The Polyhedraverse id of a body, by its key (tetrahedron, octahedron, cube, icosahedron, dodecahedron: named by look). */
export const reuleauxId = (key) => `REULEAUX_${key.toUpperCase()}`;

function curvedOf(B) {
  const k = 1 / (REULEAUX_Q * B.side), v = B.body.v;
  const positions = new Float32Array(v.length);
  for (let i = 0; i < v.length; i++) positions[i] = v[i] * k;
  const seams = new Float32Array(B.body.s.length * 3);
  B.body.s.forEach((i, j) => { seams[3 * j] = positions[3 * i]; seams[3 * j + 1] = positions[3 * i + 1]; seams[3 * j + 2] = positions[3 * i + 2]; });
  return { positions, index: Uint32Array.from(B.body.t), patch: Uint8Array.from(B.body.patch), seams };
}

export const REULEAUX_ADDITIONS = Object.fromEntries(REULEAUX_RAW.map((B) => {
  const id = reuleauxId(B.key);
  const spec = specOf(id, B.name, B.corners.map((c) => c.map((x) => x / B.side)), B.faces, true, 1);
  return [id, { ...spec, curved: curvedOf(B), reuleaux: { key: B.key, source: B.source } }];
}));
export const REULEAUX_ADDITION_IDS = Object.keys(REULEAUX_ADDITIONS);
